INSERT INTO public.questionnaires (id, title, version, description, pass_percent, is_demo, is_active) VALUES ('40000000-0000-4000-8000-000000000001', 'Pesca sportiva con canna', 1, 'Bozza formativa da validare. Bolentino, traina, attrezzature e tutela delle risorse marine.', 80, true, true);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000101', '40000000-0000-4000-8000-000000000001', 1, 'Qual è la misura minima consentita per trattenere una Cernia (Epinephelus spp.)?', '["30 cm","45 cm","60 cm","Nessun limite"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000102', '40000000-0000-4000-8000-000000000001', 2, 'Quali sono i requisiti minimi di taglia per trattenere un Tonno Rosso?', '["115 cm o 30 kg","100 cm o 20 kg","150 cm o 50 kg"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000103', '40000000-0000-4000-8000-000000000001', 3, 'La comunicazione di cattura di un Tonno Rosso (con regolare nulla osta) è obbligatoria?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000104', '40000000-0000-4000-8000-000000000001', 4, 'Qual è il limite massimo di peso giornaliero del pescato per un pescatore sportivo?', '["3 kg","5 kg","10 kg"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000105', '40000000-0000-4000-8000-000000000001', 5, 'Quanti ami sono consentiti al massimo su un palamito (coffa) per uso ricreativo?', '["100","200","500"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000106', '40000000-0000-4000-8000-000000000001', 6, 'Quante canne o lenze a mano sono consentite al massimo per ogni imbarcazione da diporto?', '["3","5","Nessun limite"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000107', '40000000-0000-4000-8000-000000000001', 7, 'È consentito vendere a ristoranti locali il pesce catturato durante una battuta di pesca sportiva?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000108', '40000000-0000-4000-8000-000000000001', 8, 'È necessaria una comunicazione al Ministero (MIPAAF) per praticare la pesca sportiva in mare in Italia?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000109', '40000000-0000-4000-8000-000000000001', 9, 'Qual è il periodo di chiusura per la pesca del pesce spada nel Mediterraneo previsto dall’articolo 10 del Regolamento (UE) 2019/1154?', '["Dal 1° gennaio al 31 marzo","Dal 1° giugno al 31 agosto","Nessun periodo di chiusura"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000110', '40000000-0000-4000-8000-000000000001', 10, 'L''uso di salpabolentini elettrici (mulinelli elettrici) per la pesca di profondità è consentito?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaires (id, title, version, description, pass_percent, is_demo, is_active) VALUES ('40000000-0000-4000-8000-000000000002', 'Pesca in apnea', 1, 'Bozza formativa da validare. Segnalazione, attrezzatura, comportamento e sicurezza in mare.', 80, true, true);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000201', '40000000-0000-4000-8000-000000000002', 1, 'È consentita la raccolta del Dattero di mare se effettuata a mano senza attrezzi?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000202', '40000000-0000-4000-8000-000000000002', 2, 'A quale distanza minima dalle spiagge frequentate da bagnanti è consentita la pesca in apnea?', '["100 metri","300 metri","500 metri"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000203', '40000000-0000-4000-8000-000000000002', 3, 'Come deve essere segnalato un pescatore in apnea in immersione?', '["Boa rossa con striscia bianca","Pallone nero","Boa gialla"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000204', '40000000-0000-4000-8000-000000000002', 4, 'A quale distanza massima dalla boa di segnalazione può operare il subacqueo?', '["25 metri","50 metri","100 metri"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000205', '40000000-0000-4000-8000-000000000002', 5, 'Qual è l''età minima per poter utilizzare un fucile subacqueo?', '["14 anni","16 anni","18 anni"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000206', '40000000-0000-4000-8000-000000000002', 6, 'È consentita la pesca in apnea nelle ore notturne (dal tramonto all''alba) con l''ausilio di una torcia?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000207', '40000000-0000-4000-8000-000000000002', 7, 'Qual è il limite di cattura giornaliero per la Cernia per un pescatore in apnea?', '["1 al giorno","2 al giorno","Nessun limite se sotto i 5 kg"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000208', '40000000-0000-4000-8000-000000000002', 8, 'Qual è il rischio fisiologico principale derivante dall''eccessiva iperventilazione prima di un tuffo?', '["Embolia gassosa","Sincope anossica","Ipotermia"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000209', '40000000-0000-4000-8000-000000000002', 9, 'L''uso dell''acquascooter nella pesca in apnea è:', '["Vietato","Consentito con fucile carico","Consentito ma il fucile deve essere scarico durante il moto"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000210', '40000000-0000-4000-8000-000000000002', 10, 'Quanti ricci di mare (Paracentrotus lividus) può raccogliere un pescatore sportivo in apnea al giorno?', '["Max 50","Max 100","Vietato"]'::jsonb);
INSERT INTO public.questionnaires (id, title, version, description, pass_percent, is_demo, is_active) VALUES ('40000000-0000-4000-8000-000000000003', 'Pesca professionale con reti', 1, 'Bozza formativa da validare. Attrezzi da posta, tracciabilità e protezione della fauna marina.', 80, true, true);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000301', '40000000-0000-4000-8000-000000000003', 1, 'Da quante "pezze" (pareti di rete) è composta una rete da posta di tipo "Tramaglio"?', '["Una","Due","Tre"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000302', '40000000-0000-4000-8000-000000000003', 2, 'Come devono essere obbligatoriamente etichettati i segnali (boe) delle reti da posta fisse?', '["Nessun obbligo","Con la matricola e sigla dell''imbarcazione","Con il nome del capitano"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000303', '40000000-0000-4000-8000-000000000003', 3, 'Come deve essere segnalata una rete da posta fissa calata durante la notte?', '["Con fari rotanti","Con boe radarabili e luci lampeggianti (gialle/bianche)","Nessuna segnalazione"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000304', '40000000-0000-4000-8000-000000000003', 4, 'Qual è la causa principale della creazione di "Reti Fantasma" (Ghost Fishing)?', '["Ancoraggio errato e forti correnti/maltempo","Reti troppo nuove","Presenza di pesci di grossa taglia"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000305', '40000000-0000-4000-8000-000000000003', 5, 'Le reti da posta fisse possono essere calate ostruendo il canale di accesso di un porto?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000306', '40000000-0000-4000-8000-000000000003', 6, 'Quale fattore determina principalmente la dimensione minima della maglia di una rete da posta?', '["La specie bersaglio (Target)","Il fondale","La lunghezza della barca"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000307', '40000000-0000-4000-8000-000000000003', 7, 'Cosa deve fare un pescatore professionista in caso di cattura accidentale di una Tartaruga Marina (Caretta caretta) viva nella rete?', '["Rimetterla subito in mare anche se ferita","Issarla a bordo, applicare le procedure di rianimazione e avvisare la Capitaneria","Venderla al mercato"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000308', '40000000-0000-4000-8000-000000000003', 8, 'In generale (salvo deroghe locali), qual è la lunghezza massima consentita per una rete da posta/tramaglio per una piccola imbarcazione costiera?', '["1.000 metri","Fino a 4.000 - 6.000 metri","Nessun limite"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000000309', '40000000-0000-4000-8000-000000000003', 9, 'I pescatori professionali hanno l''obbligo di registrare il pescato su un "Giornale di Pesca" (Logbook)?', '["Vero","Falso"]'::jsonb);
